window.officeBundle = {"date":"2026-11-19","services":{"morning_prayer":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"leader","content":"O send out your light and your truth, that they may lead me, and bring me to your holy hill, and to your dwelling."},{"line_type":"citation","content":"PSALM 43:3"}]},{"name":"Confession of Sin","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant says to the People"},{"line_type":"leader","content":"Let us humbly confess our sins to Almighty God."},{"line_type":"rubric","content":"Silence is kept. All kneeling, the Officiant and People say"},{"line_type":"congregation","content":"Almighty and most merciful Father,"},{"line_type":"congregation","content":"we have erred and strayed from your ways like lost sheep."},{"line_type":"congregation","content":"We have followed too much the devices and desires"},{"line_type":"congregation","content":"of our own hearts."},{"line_type":"congregation","content":"We have offended against your holy laws."},{"line_type":"congregation","content":"We have left undone those things which we ought to have done,"},{"line_type":"congregation","content":"and we have done those things which we ought not"},{"line_type":"congregation","content":"to have done;"},{"line_type":"congregation","content":"and apart from your grace, there is no health in us."},{"line_type":"congregation","content":"O Lord, have mercy upon us."},{"line_type":"congregation","content":"Spare all those who confess their faults."},{"line_type":"congregation","content":"Restore all those who are penitent, according to your promises"},{"line_type":"congregation","content":"declared to all people in Christ Jesus our Lord."},{"line_type":"congregation","content":"And grant, O most merciful Father, for his sake,"},{"line_type":"congregation","content":"that we may now live a godly, righteous, and sober life,"},{"line_type":"congregation","content":"to the glory of your holy Name. Amen."},{"line_type":"rubric","content":"A Deacon or layperson remains kneeling and prays"},{"line_type":"leader","content":"Grant to your faithful people, merciful Lord, pardon and peace; that we may be cleansed from all our sins, and serve you with a quiet mind; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Preces","lines":[{"line_type":"heading","content":"The Preces"},{"line_type":"rubric","content":"All stand."},{"line_type":"leader_dialogue","content":"O Lord, open our lips;"},{"line_type":"congregation_dialogue","content":"And our mouth shall proclaim your praise."},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"leader_dialogue","content":"Praise the Lord."},{"line_type":"congregation_dialogue","content":"The Lord\u2019s Name be praised."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"Venite"},{"line_type":"subheading","content":"O Come"},{"line_type":"rubric","content":"Officiant and People, all standing"},{"line_type":"leader","content":"The earth is the Lord\u2019s for he made it:"},{"line_type":"congregation","content":"O come, let us adore him."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"O come, let us sing unto the Lord; *"},{"line_type":"congregation","content":"let us heartily rejoice in the strength of our salvation."},{"line_type":"congregation","content":"Let us come before his presence with thanksgiving *"},{"line_type":"congregation","content":"and show ourselves glad in him with psalms."},{"line_type":"congregation","content":"For the Lord is a great God *"},{"line_type":"congregation","content":"and a great King above all gods."},{"line_type":"congregation","content":"In his hand are all the depths of the earth, *"},{"line_type":"congregation","content":"and the heights of the hills are his also."},{"line_type":"congregation","content":"The sea is his, for he made it, *"},{"line_type":"congregation","content":"and his hands prepared the dry land."},{"line_type":"congregation","content":"O come, let us worship and fall down, *"},{"line_type":"congregation","content":"and kneel before the Lord our Maker."},{"line_type":"congregation","content":"For he is our God, *"},{"line_type":"congregation","content":"and we are the people of his pasture,"},{"line_type":"congregation","content":"and the sheep of his hand."},{"line_type":"rubric","content":"The following verses may be omitted."},{"line_type":"congregation","content":"Today, if you will hear his voice, harden not your hearts *"},{"line_type":"congregation","content":"as in the provocation, and as in the day of temptation in the wilderness,"},{"line_type":"congregation","content":"When your fathers tested me, *"},{"line_type":"congregation","content":"and put me to the proof, though they had seen my works."},{"line_type":"congregation","content":"Forty years long was I grieved with this generation and said, *"},{"line_type":"congregation","content":"\u201cIt is a people that err in their hearts, for they have not known my ways,\u201d"},{"line_type":"congregation","content":"Of whom I swore in my wrath *"},{"line_type":"congregation","content":"that they should not enter into my rest."},{"line_type":"citation","content":"Psalm 95:1-7, 8-11"},{"line_type":"leader","content":"The earth is the Lord\u2019s for he made it:"},{"line_type":"congregation","content":"O come, let us adore him."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalm Appointed"},{"line_type":"subheading","content":"Sixty Day Cycle"},{"line_type":"heading","content":"Psalm 50"},{"line_type":"subheading","content":"Deus deorum"},{"line_type":"leader","content":"The L\u1d0f\u0280\u1d05, even the most mighty God, has spoken *","preface":1},{"line_type":"leader","content":"and called the world, from the rising of the sun to the going down thereof."},{"line_type":"congregation","content":"Out of Zion, perfect in her beauty, *","preface":2},{"line_type":"congregation","content":"has God shone forth in glory."},{"line_type":"leader","content":"Our God shall come and shall not keep silence; *","preface":3},{"line_type":"leader","content":"there shall go before him a consuming fire, and a mighty tempest shall be stirred up round about him."},{"line_type":"congregation","content":"He shall call to the heavens above, *","preface":4},{"line_type":"congregation","content":"and to the earth beneath, that he may judge his people:"},{"line_type":"leader","content":"\u201cGather my faithful together unto me, *","preface":5},{"line_type":"leader","content":"those who have made a covenant with me by sacrifice.\u201d"},{"line_type":"congregation","content":"And the heavens shall declare his righteousness, *","preface":6},{"line_type":"congregation","content":"for God himself is Judge."},{"line_type":"leader","content":"\u201cHear, O my people, and I will speak; *","preface":7},{"line_type":"leader","content":"I myself will testify against you, O Israel, for I am God, even your God."},{"line_type":"congregation","content":"I will not rebuke you because of your sacrifices, or for your burnt offerings, *","preface":8},{"line_type":"congregation","content":"because they are always before me."},{"line_type":"leader","content":"I will take no bull calf out of your house, *","preface":9},{"line_type":"leader","content":"nor he-goat out of your folds."},{"line_type":"congregation","content":"For all the beasts of the forest are mine, *","preface":10},{"line_type":"congregation","content":"and so are the cattle upon a thousand hills."},{"line_type":"leader","content":"I know all the birds of the air, *","preface":11},{"line_type":"leader","content":"and the wild beasts of the field are in my sight."},{"line_type":"congregation","content":"If I were hungry, I would not tell you, *","preface":12},{"line_type":"congregation","content":"for the whole world is mine, and all that is therein."},{"line_type":"leader","content":"Do you think that I will eat the flesh of bulls *","preface":13},{"line_type":"leader","content":"and drink the blood of goats?"},{"line_type":"congregation","content":"Offer unto God a sacrifice of thanksgiving, *","preface":14},{"line_type":"congregation","content":"and pay your vows unto the Most High,"},{"line_type":"leader","content":"And call upon me in the time of trouble; *","preface":15},{"line_type":"leader","content":"so will I hear you, and you shall praise me.\u201d"},{"line_type":"congregation","content":"But to the ungodly God says: *","preface":16},{"line_type":"congregation","content":"\u201cWhy do you recite my laws, and take my covenant in your mouth,"},{"line_type":"leader","content":"Though you hate to be disciplined, *","preface":17},{"line_type":"leader","content":"and have cast my words behind you?"},{"line_type":"congregation","content":"When you saw a thief, you agreed with him, *","preface":18},{"line_type":"congregation","content":"and you have taken part with adulterers."},{"line_type":"leader","content":"You have let your mouth speak wickedness, *","preface":19},{"line_type":"leader","content":"and with your tongue you have set forth deceit."},{"line_type":"congregation","content":"You sat and spoke against your brother; *","preface":20},{"line_type":"congregation","content":"yes, and have slandered your own mother\u2019s son."},{"line_type":"leader","content":"These things you have done, and I held my tongue, *","preface":21},{"line_type":"leader","content":"and you thought wickedly that I am such a one as yourself."},{"line_type":"congregation","content":"But I will reprove you, *","preface":22},{"line_type":"congregation","content":"and set before you the things that you have done."},{"line_type":"leader","content":"O consider this, you who forget God, *","preface":23},{"line_type":"leader","content":"lest I tear you in pieces, and there be none to deliver you."},{"line_type":"congregation","content":"Whoever offers me a sacrifice of thanksgiving honors me, *","preface":24},{"line_type":"congregation","content":"and to him who orders his way aright will I show the salvation of God.\u201d"},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"First Reading","lines":[{"line_type":"heading","content":"The First Lesson"},{"line_type":"subheading","content":"Judith 13"},{"line_type":"reader","content":"A reading from the Book of Judith, beginning with the thirteenth chapter, the first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='firstreading_3926f5e1-5a85-5abb-9f5f-857ec17782ec'></span><p><span class=\"cc vnumVis\">13</span>Now when the evening was come, his servants made haste to depart, and Bagoas shut his tent without, and dismissed the waiters from the presence of his lord; and they went to their beds: for they were all weary, because the feast had been long. <sup>2\u00a0</sup>And Judith was left along in the tent, and Holofernes lying along upon his bed: for he was filled with wine. <sup>3\u00a0</sup>Now Judith had commanded her maid to stand without her bedchamber, and to wait for her. coming forth, as she did daily: for she said she would go forth to her prayers, and she spake to Bagoas according to the same purpose. <sup>4\u00a0</sup>So all went forth and none was left in the bedchamber, neither little nor great. Then Judith, standing by his bed, said in her heart, O Lord God of all power, look at this present upon the works of mine hands for the exaltation of Jerusalem. <sup>5\u00a0</sup>For now is the time to help thine inheritance, and to execute thine enterprizes to the destruction of the enemies which are risen against us. <sup>6\u00a0</sup>Then she came to the pillar of the bed, which was at Holofernes\u2019 head, and took down his fauchion from thence, <sup>7\u00a0</sup>And approached to his bed, and took hold of the hair of his head, and said, Strengthen me, O Lord God of Israel, this day. <sup>8\u00a0</sup>And she smote twice upon his neck with all her might, and she took away his head from him. <sup>9\u00a0</sup>And tumbled his body down from the bed, and pulled down the canopy from the pillars; and anon after she went forth, and gave Holofernes his head to her maid; <sup>10\u00a0</sup>And she put it in her bag of meat: so they twain went together according to their custom unto prayer: and when they passed the camp, they compassed the valley, and went up the mountain of Bethulia, and came to the gates thereof. <sup>11\u00a0</sup>Then said Judith afar off, to the watchmen at the gate, Open, open now the gate: God, even our God, is with us, to shew his power yet in Jerusalem, and his forces against the enemy, as he hath even done this day. <sup>12\u00a0</sup>Now when the men of her city heard her voice, they made haste to go down to the gate of their city, and they called the elders of the city. <sup>13\u00a0</sup>And then they ran all together, both small and great, for it was strange unto them that she was come: so they opened the gate, and received them, and made a fire for a light, and stood round about them. <sup>14\u00a0</sup>Then she said to them with a loud voice, Praise, praise God, praise God, I say, for he hath not taken away his mercy from the house of Israel, but hath destroyed our enemies by mine hands this night. <sup>15\u00a0</sup>So she took the head out of the bag, and shewed it, and said unto them, behold the head of Holofernes, the chief captain of the army of Assur, and behold the canopy, wherein he did lie in his drunkenness; and the Lord hath smitten him by the hand of a woman. <sup>16\u00a0</sup>As the Lord liveth, who hath kept me in my way that I went, my countenance hath deceived him to his destruction, and yet hath he not committed sin with me, to defile and shame me. <sup>17\u00a0</sup>Then all the people were wonderfully astonished, and bowed themselves and worshipped God, and said with one accord, Blessed be thou, O our God, which hast this day brought to nought the enemies of thy people. <sup>18\u00a0</sup>Then said Ozias unto her, O daughter, blessed art thou of the most high God above all the women upon the earth; and blessed be the Lord God, which hath created the heavens and the earth, which hath directed thee to the cutting off of the head of the chief of our enemies. <sup>19\u00a0</sup>For this thy confidence shall not depart from the heart of men, which remember the power of God for ever. <sup>20\u00a0</sup>And God turn these things to thee for a perpetual praise, to visit thee in good things because thou hast not spared thy life for the affliction of our nation, but hast revenged our ruin, walking a straight way before our God. And all the people said; So be it, so be it.<br/></p>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"Here ends the Reading."}]},{"name":"First Canticle","lines":[{"line_type":"heading","content":"TE DEUM LAUDAMUS"},{"line_type":"subheading","content":"We Praise You, O God"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"We praise you, O God; we acclaim you as Lord; *"},{"line_type":"congregation","content":"all creation worships you, the Father everlasting."},{"line_type":"congregation","content":"To you all angels, all the powers of heaven, *"},{"line_type":"congregation","content":"the cherubim and seraphim, sing in endless praise:"},{"line_type":"congregation","content":"Holy, Holy, Holy, Lord God of power and might, *"},{"line_type":"congregation","content":"heaven and earth are full of your glory."},{"line_type":"congregation","content":"The glorious company of apostles praise you. *"},{"line_type":"congregation","content":"The noble fellowship of prophets praise you."},{"line_type":"congregation","content":"The white-robed army of martyrs praise you. *"},{"line_type":"congregation","content":"Throughout the world the holy Church acclaims you:"},{"line_type":"congregation","content":"Father, of majesty unbounded,"},{"line_type":"congregation","content":"your true and only Son, worthy of all praise, *"},{"line_type":"congregation","content":"and the Holy Spirit, advocate and guide."},{"line_type":"congregation","content":"You, Christ, are the king of glory, *"},{"line_type":"congregation","content":"the eternal Son of the Father."},{"line_type":"congregation","content":"When you took our flesh to set us free *"},{"line_type":"congregation","content":"you humbly chose the Virgin\u2019s womb."},{"line_type":"congregation","content":"You overcame the sting of death *"},{"line_type":"congregation","content":"and opened the kingdom of heaven to all believers."},{"line_type":"congregation","content":"You are seated at God\u2019s right hand in glory. *"},{"line_type":"congregation","content":"We believe that you will come to be our judge."},{"line_type":"congregation","content":"Come then, Lord, and help your people, *"},{"line_type":"congregation","content":"bought with the price of your own blood,"},{"line_type":"congregation","content":"and bring us with your saints *"},{"line_type":"congregation","content":"to glory everlasting."},{"line_type":"rubric","content":"The following verses may be omitted"},{"line_type":"congregation","content":"Save your people, Lord, and bless your inheritance;*"},{"line_type":"congregation","content":"govern and uphold them now and always."},{"line_type":"congregation","content":"Day by day we bless you; *"},{"line_type":"congregation","content":"we praise your Name for ever."},{"line_type":"congregation","content":"Keep us today, Lord, from all sin; *"},{"line_type":"congregation","content":"have mercy on us, Lord, have mercy."},{"line_type":"congregation","content":"Lord, show us your love and mercy, *"},{"line_type":"congregation","content":"for we have put our trust in you."},{"line_type":"congregation","content":"In you, Lord, is our hope; *"},{"line_type":"congregation","content":"let us never be put to shame."}]},{"name":"Second Reading","lines":[{"line_type":"heading","content":"The Second Lesson"},{"line_type":"subheading","content":"Acts 18:1-23"},{"line_type":"reader","content":"A reading from the Acts of the Apostles, beginning with the eighteenth chapter, the first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='secondreading_a18f5318-0dbf-5548-8b29-d6f89f674d55'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<p class=\"top-1 chapter-2\"><span class=\"text Acts-18-1\" id=\"en-AKJV-27559\"><span class=\"chapternum\">18\u00a0</span>After these things Paul departed from Athens, and came to Corinth; </span> <span class=\"text Acts-18-2\" id=\"en-AKJV-27560\"><sup class=\"versenum\">2\u00a0</sup>and found a certain Jew named Aquila, born in Pontus, lately come from Italy, with his wife Priscilla; (because that Claudius had commanded all Jews to depart from Rome:) and came unto them. </span> <span class=\"text Acts-18-3\" id=\"en-AKJV-27561\"><sup class=\"versenum\">3\u00a0</sup>And because he was of the same craft, he abode with them, and wrought: for by their occupation they were tentmakers. </span> <span class=\"text Acts-18-4\" id=\"en-AKJV-27562\"><sup class=\"versenum\">4\u00a0</sup>And he reasoned in the synagogue every sabbath, and persuaded the Jews and the Greeks.</span></p><span data-line-id='secondreading_5bf21759-71bf-5440-8336-75553462238f'></span> <p><span class=\"text Acts-18-5\" id=\"en-AKJV-27563\"><sup class=\"versenum\">5\u00a0</sup>And when Silas and Timotheus were come from Macedonia, Paul was pressed in the spirit, and testified to the Jews that Jesus was Christ. </span> <span class=\"text Acts-18-6\" id=\"en-AKJV-27564\"><sup class=\"versenum\">6\u00a0</sup>And when they opposed themselves, and blasphemed, he shook his raiment, and said unto them, Your blood be upon your own heads; I am clean: from henceforth I will go unto the Gentiles.</span></p><span data-line-id='secondreading_4a25d65d-35fb-5522-b539-2443f350b5b6'></span> <p><span class=\"text Acts-18-7\" id=\"en-AKJV-27565\"><sup class=\"versenum\">7\u00a0</sup>And he departed thence, and entered into a certain man\u2019s house, named Justus, one that worshipped God, whose house joined hard to the synagogue. </span> <span class=\"text Acts-18-8\" id=\"en-AKJV-27566\"><sup class=\"versenum\">8\u00a0</sup>And Crispus, the chief ruler of the synagogue, believed on the Lord with all his house; and many of the Corinthians hearing believed, and were baptized. </span> <span class=\"text Acts-18-9\" id=\"en-AKJV-27567\"><sup class=\"versenum\">9\u00a0</sup>Then spake the Lord to Paul in the night by a vision, Be not afraid, but speak, and hold not thy peace: </span> <span class=\"text Acts-18-10\" id=\"en-AKJV-27568\"><sup class=\"versenum\">10\u00a0</sup>for I am with thee, and no man shall set on thee to hurt thee: for I have much people in this city. </span> <span class=\"text Acts-18-11\" id=\"en-AKJV-27569\"><sup class=\"versenum\">11\u00a0</sup>And he continued there a year and six months, teaching the word of God among them.</span></p><span data-line-id='secondreading_a1916fd8-15b5-5960-a028-ce508ffe5e32'></span> <p><span class=\"text Acts-18-12\" id=\"en-AKJV-27570\"><sup class=\"versenum\">12\u00a0</sup>And when Gallio was the deputy of Achaia, the Jews made insurrection with one accord against Paul, and brought him to the judgment seat, </span> <span class=\"text Acts-18-13\" id=\"en-AKJV-27571\"><sup class=\"versenum\">13\u00a0</sup>saying, This fellow persuadeth men to worship God contrary to the law. </span> <span class=\"text Acts-18-14\" id=\"en-AKJV-27572\"><sup class=\"versenum\">14\u00a0</sup>And when Paul was now about to open his mouth, Gallio said unto the Jews, If it were a matter of wrong or wicked lewdness, O ye Jews, reason would that I should bear with you: </span> <span class=\"text Acts-18-15\" id=\"en-AKJV-27573\"><sup class=\"versenum\">15\u00a0</sup>but if it be a question of words and names, and of your law, look ye to it; for I will be no judge of such matters. </span> <span class=\"text Acts-18-16\" id=\"en-AKJV-27574\"><sup class=\"versenum\">16\u00a0</sup>And he drave them from the judgment seat. </span> <span class=\"text Acts-18-17\" id=\"en-AKJV-27575\"><sup class=\"versenum\">17\u00a0</sup>Then all the Greeks took Sosthenes, the chief ruler of the synagogue, and beat him before the judgment seat. And Gallio cared for none of those things.</span></p><span data-line-id='secondreading_dd3b7bba-bbd8-5bd4-86cd-9b9e861be7f7'></span> <p><span class=\"text Acts-18-18\" id=\"en-AKJV-27576\"><sup class=\"versenum\">18\u00a0</sup>And Paul after this tarried there yet a good while, and then took his leave of the brethren, and sailed thence into Syria, and with him Priscilla and Aquila; having shorn his head in Cenchrea: for he had a vow. </span> <span class=\"text Acts-18-19\" id=\"en-AKJV-27577\"><sup class=\"versenum\">19\u00a0</sup>And he came to Ephesus, and left them there: but he himself entered into the synagogue, and reasoned with the Jews. </span> <span class=\"text Acts-18-20\" id=\"en-AKJV-27578\"><sup class=\"versenum\">20\u00a0</sup>When they desired him to tarry longer time with them, he consented not; </span> <span class=\"text Acts-18-21\" id=\"en-AKJV-27579\"><sup class=\"versenum\">21\u00a0</sup>but bade them farewell, saying, I must by all means keep this feast that cometh in Jerusalem: but I will return again unto you, if God will. And he sailed from Ephesus. </span> <span class=\"text Acts-18-22\" id=\"en-AKJV-27580\"><sup class=\"versenum\">22\u00a0</sup>And when he had landed at C\u00e6sarea, and gone up, and saluted the church, he went down to Antioch. </span> <span class=\"text Acts-18-23\" id=\"en-AKJV-27581\"><sup class=\"versenum\">23\u00a0</sup>And after he had spent some time there, he departed, and went over all the country of Galatia and Phrygia in order, strengthening all the disciples.</span></p>\n</div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"Second Canticle","lines":[{"line_type":"heading","content":"BENEDICTUS"},{"line_type":"subheading","content":"The Song of Zechariah"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"Blessed be the Lord, the God of Israel; *"},{"line_type":"congregation","content":"he has come to his people and set them free."},{"line_type":"congregation","content":"He has raised up for us a mighty savior, *"},{"line_type":"congregation","content":"born of the house of his servant David."},{"line_type":"congregation","content":"Through his holy prophets he promised of old"},{"line_type":"congregation","content":"that he would save us from our enemies, *"},{"line_type":"congregation","content":"from the hands of all who hate us."},{"line_type":"congregation","content":"He promised to show mercy to our fathers *"},{"line_type":"congregation","content":"and to remember his holy covenant."},{"line_type":"congregation","content":"This was the oath he swore to our father Abraham, *"},{"line_type":"congregation","content":"to set us free from the hands of our enemies,"},{"line_type":"congregation","content":"Free to worship him without fear, *"},{"line_type":"congregation","content":"holy and righteous in his sight"},{"line_type":"congregation","content":"all the days of our life."},{"line_type":"congregation","content":"You, my child, shall be called the prophet of the Most High, *"},{"line_type":"congregation","content":"for you will go before the Lord to prepare his way,"},{"line_type":"congregation","content":"To give his people knowledge of salvation *"},{"line_type":"congregation","content":"by the forgiveness of their sins."},{"line_type":"congregation","content":"In the tender compassion of our God *"},{"line_type":"congregation","content":"the dawn from on high shall break upon us,"},{"line_type":"congregation","content":"To shine on those who dwell in darkness"},{"line_type":"congregation","content":"and in the shadow of death, *"},{"line_type":"congregation","content":"and to guide our feet into the way of peace."},{"line_type":"citation","content":"LUKE 1:68-79"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"The Apostle's Creed","lines":[{"line_type":"heading","content":"The Apostles' Creed"},{"line_type":"rubric","content":"Officiant and People together, all standing"},{"line_type":"congregation","content":"I believe in God, the Father almighty,"},{"line_type":"congregation","content":"creator of heaven and earth."},{"line_type":"congregation","content":"I believe in Jesus Christ, his only Son, our Lord."},{"line_type":"congregation","content":"He was conceived by the Holy Spirit"},{"line_type":"congregation","content":"and born of the Virgin Mary."},{"line_type":"congregation","content":"He suffered under Pontius Pilate,"},{"line_type":"congregation","content":"was crucified, died, and was buried."},{"line_type":"congregation","content":"He descended to the dead."},{"line_type":"congregation","content":"On the third day he rose again."},{"line_type":"congregation","content":"He ascended into heaven,"},{"line_type":"congregation","content":"and is seated at the right hand of the Father."},{"line_type":"congregation","content":"He will come again to judge the living and the dead."},{"line_type":"congregation","content":"I believe in the Holy Spirit,"},{"line_type":"congregation","content":"the holy catholic Church,"},{"line_type":"congregation","content":"the communion of saints,"},{"line_type":"congregation","content":"the forgiveness of sins,"},{"line_type":"congregation","content":"the resurrection of the body,"},{"line_type":"congregation","content":"and the life everlasting. Amen."}]},{"name":"The Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"The Lord be with you.","preface":"Officiant"},{"line_type":"congregation_dialogue","content":"And with your spirit.","preface":"People"},{"line_type":"leader_dialogue","content":"Let us pray.","preface":"Officiant"},{"line_type":"rubric","content":"The People kneel or stand."},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"heading","content":"The Suffrages"},{"line_type":"leader_dialogue","content":"O Lord, show your mercy upon us;"},{"line_type":"congregation_dialogue","content":"And grant us your salvation."},{"line_type":"leader_dialogue","content":"O Lord, guide those who govern us"},{"line_type":"congregation_dialogue","content":"And lead us in the way of justice and truth."},{"line_type":"leader_dialogue","content":"Clothe your ministers with righteousness"},{"line_type":"congregation_dialogue","content":"And let your people sing with joy."},{"line_type":"leader_dialogue","content":"O Lord, save your people"},{"line_type":"congregation_dialogue","content":"And bless your inheritance."},{"line_type":"leader_dialogue","content":"Give peace in our time, O Lord"},{"line_type":"congregation_dialogue","content":"And defend us by your mighty power."},{"line_type":"leader_dialogue","content":"Let not the needy, O Lord, be forgotten"},{"line_type":"congregation_dialogue","content":"Nor the hope of the poor be taken away."},{"line_type":"leader_dialogue","content":"Create in us clean hearts, O God"},{"line_type":"congregation_dialogue","content":"And take not your Holy Spirit from us."}]},{"name":"Collect(s) of the Day","lines":[{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Thursday after the Twenty-fifth Sunday after Pentecost, or the Twenty-fourth Sunday after Trinity (Proper 28)"},{"line_type":"leader","content":"Stir up, O Lord, the wills of your faithful people, that bringing forth in abundance the fruit of good works, they may be abundantly rewarded when our Savior Jesus Christ comes to restore all things; who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Hilda, Abbess of Whitby, 680"},{"line_type":"leader","content":"O God, your blessed Son became poor for our sake, and chose the Cross over the kingdoms of this world: Deliver us from an inordinate love of worldly things, that we, inspired by the devotion of your servant Hilda, may seek you with singleness of heart, behold your glory by faith, and attain to the riches of your everlasting kingdom, where we shall be united with our Savior Jesus Christ; who lives and reigns with you and the Holy Spirit, one God, now and for ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Additional Collects","lines":[{"line_type":"heading","content":"A Collect for Guidance"},{"line_type":"subheading","content":"Thursday"},{"line_type":"leader","content":"Heavenly Father, in you we live and move and have our being: We humbly pray you so to guide and govern us by your Holy Spirit, that in all the cares and occupations of our life we may not forget you, but may remember that we are ever walking in your sight; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"A Prayer for Mission"},{"line_type":"leader","content":"O God, you have made of one blood all the peoples of the earth, and sent your blessed Son to preach peace to those who are far off and to those who are near: Grant that people everywhere may seek after you and find you; bring the nations into your fold; pour out your Spirit upon all flesh; and hasten the coming of your kingdom; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Intercessions, Thanksgivings, and Praise","lines":[{"line_type":"heading","content":"Intercessions, Thanksgivings, and Praise"},{"line_type":"rubric","content":"The Officiant may invite the People to offer intercessions and thanksgivings."},{"line_type":"rubric","content":"A hymn or anthem may be sung."},{"line_type":"speaker","content":"Let us pause to offer our own intercessions and thanksgivings."}]},{"name":"Final Prayers","lines":[{"line_type":"heading","content":"The General Thanksgiving"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Almighty God, Father of all mercies,"},{"line_type":"congregation","content":"we your unworthy servants give you humble thanks"},{"line_type":"congregation","content":"for all your goodness and loving-kindness"},{"line_type":"congregation","content":"to us and to all whom you have made."},{"line_type":"congregation","content":"We bless you for our creation, preservation,"},{"line_type":"congregation","content":"and all the blessings of this life;"},{"line_type":"congregation","content":"but above all for your immeasurable love"},{"line_type":"congregation","content":"in the redemption of the world by our Lord Jesus Christ;"},{"line_type":"congregation","content":"for the means of grace, and for the hope of glory."},{"line_type":"congregation","content":"And, we pray, give us such an awareness of your mercies,"},{"line_type":"congregation","content":"that with truly thankful hearts we may show forth your praise,"},{"line_type":"congregation","content":"not only with our lips, but in our lives,"},{"line_type":"congregation","content":"by giving up our selves to your service,"},{"line_type":"congregation","content":"and by walking before you"},{"line_type":"congregation","content":"in holiness and righteousness all our days;"},{"line_type":"congregation","content":"Through Jesus Christ our Lord,"},{"line_type":"congregation","content":"to whom, with you and the Holy Spirit,"},{"line_type":"congregation","content":"be honor and glory throughout all ages. Amen."},{"line_type":"heading","content":"A Prayer of St. John Chrysostom"},{"line_type":"leader","content":"Almighty God, you have given us grace at this time, with one accord to make our common supplications to you; and you have promised through your well-beloved Son that when two or three are gathered together in his Name you will grant their requests: Fulfill now, O Lord, our desires and petitions as may be best for us; granting us in this world knowledge of your truth, and in the age to come life everlasting."},{"line_type":"congregation","content":"Amen."}]},{"name":"Dismissal","lines":[{"line_type":"heading","content":"Dismissal and Grace"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"May the God of hope fill us with all joy and peace in believing through the power of the Holy Spirit."},{"line_type":"congregation","content":"Amen."},{"line_type":"citation","content":"ROMANS 15:13"}]}],"midday_prayer":[{"name":"Invitatory","lines":[{"line_type":"heading","content":"Invitatory"},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen. Alleluia."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalms"},{"line_type":"heading","content":"Psalm 119:105-112"},{"line_type":"subheading","content":"Beati immaculati"},{"line_type":"leader","content":"Your word is a lantern to my feet *","preface":105},{"line_type":"leader","content":"and a light upon my path."},{"line_type":"congregation","content":"I have sworn and am steadfastly purposed *","preface":106},{"line_type":"congregation","content":"to keep your righteous judgments."},{"line_type":"leader","content":"I am troubled above measure; *","preface":107},{"line_type":"leader","content":"revive me, O L\u1d0f\u0280\u1d05, according to your word."},{"line_type":"congregation","content":"Let the freewill offerings of my mouth please you, O L\u1d0f\u0280\u1d05; *","preface":108},{"line_type":"congregation","content":"and teach me your judgments."},{"line_type":"leader","content":"My life is always in my hand, *","preface":109},{"line_type":"leader","content":"yet I do not forget your law."},{"line_type":"congregation","content":"The ungodly have laid a snare for me, *","preface":110},{"line_type":"congregation","content":"yet I have not strayed from your commandments."},{"line_type":"leader","content":"Your testimonies have I claimed as my heritage for ever, *","preface":111},{"line_type":"leader","content":"and why? They are the very joy of my heart."},{"line_type":"congregation","content":"I have applied my heart to fulfill your statutes always, *","preface":112},{"line_type":"congregation","content":"even unto the end. Samekh"},{"line_type":"heading","content":"Psalm 121"},{"line_type":"subheading","content":"Levavi oculos"},{"line_type":"leader","content":"I will lift up my eyes unto the hills; *","preface":1},{"line_type":"leader","content":"from whence comes my help?"},{"line_type":"congregation","content":"My help comes from the L\u1d0f\u0280\u1d05, *","preface":2},{"line_type":"congregation","content":"who has made heaven and earth."},{"line_type":"leader","content":"He will not let your foot be moved, *","preface":3},{"line_type":"leader","content":"and he who keeps you will not sleep."},{"line_type":"congregation","content":"Behold, he who keeps Israel *","preface":4},{"line_type":"congregation","content":"shall neither slumber nor sleep."},{"line_type":"leader","content":"The L\u1d0f\u0280\u1d05 himself is your keeper; *","preface":5},{"line_type":"leader","content":"the L\u1d0f\u0280\u1d05 is your defense upon your right hand,"},{"line_type":"congregation","content":"So that the sun shall not burn you by day, *","preface":6},{"line_type":"congregation","content":"neither the moon by night."},{"line_type":"leader","content":"The L\u1d0f\u0280\u1d05 shall preserve you from all evil; *","preface":7},{"line_type":"leader","content":"indeed, it is he who shall keep your soul."},{"line_type":"congregation","content":"The L\u1d0f\u0280\u1d05 shall preserve your going out and your coming in, *","preface":8},{"line_type":"congregation","content":"from this time forth for evermore."},{"line_type":"heading","content":"Psalm 124"},{"line_type":"subheading","content":"Nisi quia Dominus"},{"line_type":"leader","content":"If the L\u1d0f\u0280\u1d05 himself had not been on our side, now may Israel say: *","preface":1},{"line_type":"leader","content":"if the L\u1d0f\u0280\u1d05 himself had not been on our side, when men rose up against us,"},{"line_type":"congregation","content":"Then would they have swallowed us up alive, *","preface":2},{"line_type":"congregation","content":"when they were so wrathfully displeased with us;"},{"line_type":"leader","content":"Then the waters would have drowned us, and the torrent gone over us; *","preface":3},{"line_type":"leader","content":"then the raging waters would have gone clean over us."},{"line_type":"congregation","content":"But praised be the L\u1d0f\u0280\u1d05, *","preface":4},{"line_type":"congregation","content":"who has not given us over to be prey for their teeth."},{"line_type":"leader","content":"We escaped like a bird out of the snare of the fowler; *","preface":5},{"line_type":"leader","content":"the snare is broken, and we have been delivered."},{"line_type":"congregation","content":"Our help is in the Name of the L\u1d0f\u0280\u1d05, *","preface":6},{"line_type":"congregation","content":"the maker of heaven and earth."},{"line_type":"heading","content":"Psalm 126"},{"line_type":"subheading","content":"In convertendo"},{"line_type":"leader","content":"When the L\u1d0f\u0280\u1d05 overturned the captivity of Zion, *","preface":1},{"line_type":"leader","content":"then were we like those who dream."},{"line_type":"congregation","content":"Then was our mouth filled with laughter *","preface":2},{"line_type":"congregation","content":"and our tongue with shouts of joy."},{"line_type":"leader","content":"Then they said among the nations, *","preface":3},{"line_type":"leader","content":"\u201cThe L\u1d0f\u0280\u1d05 has done great things for them.\u201d"},{"line_type":"congregation","content":"Indeed, the L\u1d0f\u0280\u1d05 has done great things for us already, *","preface":4},{"line_type":"congregation","content":"whereof we rejoice."},{"line_type":"leader","content":"Overturn our captivity, O L\u1d0f\u0280\u1d05, *","preface":5},{"line_type":"leader","content":"as when streams refresh the deserts of the south."},{"line_type":"congregation","content":"Those who sow in tears *","preface":6},{"line_type":"congregation","content":"shall reap with songs of joy."},{"line_type":"leader","content":"He who goes on his way weeping and bears good seed *","preface":7},{"line_type":"leader","content":"shall doubtless come again with joy, and bring his sheaves with him."},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Scripture","lines":[{"line_type":"heading","content":"The Reading"},{"line_type":"leader","content":"Jesus said, \u201cNow is the judgment of this world; now will the ruler of this world be cast out. And I, when I am lifted up from the earth, will draw all people to myself.\u201d"},{"line_type":"citation","content":"JOHN 12:31-32"},{"line_type":"leader_dialogue","content":"The Word of the Lord"},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"A meditation, silent or spoken, may follow."}]},{"name":"Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"I will bless the Lord at all times."},{"line_type":"congregation_dialogue","content":"His praise shall continually be in my mouth."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"spacer","content":""},{"line_type":"leader_dialogue","content":"O Lord, hear our prayer"},{"line_type":"congregation_dialogue","content":"And let our cry come to you."},{"line_type":"leader_dialogue","content":"Let us pray."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Blessed Savior, at this hour you hung upon the Cross, stretching out your loving arms: Grant that all the peoples of the earth may look to you and be saved; for your tender mercies\u2019 sake."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Pour your grace into our hearts, O Lord, that we who have known the incarnation of your Son Jesus Christ, announced by an angel to the Virgin Mary, may by his Cross and passion be brought to the glory of his resurrection; who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Conclusion","lines":[{"line_type":"heading","content":"The Dismissal"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"The Officiant concludes with the following"},{"line_type":"leader","content":"The grace of our Lord Jesus Christ, and the love of God, and the fellowship of the Holy Spirit, be with us all evermore."},{"line_type":"congregation","content":"Amen."}]}],"evening_prayer":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"leader","content":"O worship the Lord in the beauty of holiness; let the whole earth stand in awe of him."},{"line_type":"citation","content":"PSALM 96:9"}]},{"name":"Confession of Sin","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant says to the People"},{"line_type":"leader","content":"Let us humbly confess our sins to Almighty God."},{"line_type":"rubric","content":"Silence is kept. All kneeling, the Officiant and People say"},{"line_type":"congregation","content":"Almighty and most merciful Father,"},{"line_type":"congregation","content":"we have erred and strayed from your ways like lost sheep."},{"line_type":"congregation","content":"We have followed too much the devices and desires"},{"line_type":"congregation","content":"of our own hearts."},{"line_type":"congregation","content":"We have offended against your holy laws."},{"line_type":"congregation","content":"We have left undone those things which we ought to have done,"},{"line_type":"congregation","content":"and we have done those things which we ought not"},{"line_type":"congregation","content":"to have done;"},{"line_type":"congregation","content":"and apart from your grace, there is no health in us."},{"line_type":"congregation","content":"O Lord, have mercy upon us."},{"line_type":"congregation","content":"Spare all those who confess their faults."},{"line_type":"congregation","content":"Restore all those who are penitent, according to your promises"},{"line_type":"congregation","content":"declared to all people in Christ Jesus our Lord."},{"line_type":"congregation","content":"And grant, O most merciful Father, for his sake,"},{"line_type":"congregation","content":"that we may now live a godly, righteous, and sober life,"},{"line_type":"congregation","content":"to the glory of your holy Name. Amen."},{"line_type":"rubric","content":"A Deacon or layperson remains kneeling and prays"},{"line_type":"leader","content":"Grant to your faithful people, merciful Lord, pardon and peace; that we may be cleansed from all our sins, and serve you with a quiet mind; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Preces","lines":[{"line_type":"heading","content":"The Preces"},{"line_type":"rubric","content":"All stand."},{"line_type":"leader_dialogue","content":"O Lord, open our lips;"},{"line_type":"congregation_dialogue","content":"And our mouth shall proclaim your praise."},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"leader_dialogue","content":"Praise the Lord."},{"line_type":"congregation_dialogue","content":"The Lord\u2019s Name be praised."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"PHOS HILARON"},{"line_type":"subheading","content":"O Gladsome Light"},{"line_type":"congregation","content":"O gladsome light,"},{"line_type":"congregation","content":"pure brightness of the everliving Father in heaven, *"},{"line_type":"congregation","content":"O Jesus Christ, holy and blessed!"},{"line_type":"congregation","content":"Now as we come to the setting of the sun,"},{"line_type":"congregation","content":"and our eyes behold the vesper light, *"},{"line_type":"congregation","content":"we sing your praises, O God: Father, Son, and Holy Spirit."},{"line_type":"congregation","content":"You are worthy at all times to be praised by happy voices, *"},{"line_type":"congregation","content":"O Son of God, O Giver of Life,"},{"line_type":"congregation","content":"and to be glorified through all the worlds."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalm Appointed"},{"line_type":"subheading","content":"Sixty Day Cycle"},{"line_type":"heading","content":"Psalm 51"},{"line_type":"subheading","content":"Miserere mei, Deus"},{"line_type":"leader","content":"Have mercy upon me, O God, in your great goodness; *","preface":1},{"line_type":"leader","content":"according to the multitude of your mercies wipe away my offences."},{"line_type":"congregation","content":"Wash me thoroughly from my wickedness *","preface":2},{"line_type":"congregation","content":"and cleanse me from my sin."},{"line_type":"leader","content":"For I acknowledge my faults, *","preface":3},{"line_type":"leader","content":"and my sin is ever before me."},{"line_type":"congregation","content":"Against you only have I sinned, and done this evil in your sight, *","preface":4},{"line_type":"congregation","content":"so that you are justified in your sentence, and blameless in your judgment."},{"line_type":"leader","content":"Behold, I was brought forth in wickedness, *","preface":5},{"line_type":"leader","content":"and in sin my mother conceived me."},{"line_type":"congregation","content":"But behold, you desire truth in the inward parts *","preface":6},{"line_type":"congregation","content":"and shall make me understand wisdom secretly."},{"line_type":"leader","content":"You shall purge me with hyssop, and I shall be clean; *","preface":7},{"line_type":"leader","content":"you shall wash me, and I shall be whiter than snow."},{"line_type":"congregation","content":"You shall make me hear of joy and gladness, *","preface":8},{"line_type":"congregation","content":"that the bones which you have broken may rejoice."},{"line_type":"leader","content":"Turn your face from my sins, *","preface":9},{"line_type":"leader","content":"and blot out all my misdeeds."},{"line_type":"congregation","content":"Create in me a clean heart, O God, *","preface":10},{"line_type":"congregation","content":"and renew a right spirit within me."},{"line_type":"leader","content":"Cast me not away from your presence, *","preface":11},{"line_type":"leader","content":"and take not your holy Spirit from me."},{"line_type":"congregation","content":"O give me the comfort of your help again, *","preface":12},{"line_type":"congregation","content":"and sustain me with your willing Spirit."},{"line_type":"leader","content":"Then shall I teach your ways unto the wicked, *","preface":13},{"line_type":"leader","content":"and sinners shall return unto you."},{"line_type":"congregation","content":"Deliver me from blood-guilt, O God, the God of my salvation, *","preface":14},{"line_type":"congregation","content":"and my tongue shall sing of your righteousness."},{"line_type":"leader","content":"O Lord, open my lips, *","preface":15},{"line_type":"leader","content":"and my mouth shall show forth your praise."},{"line_type":"congregation","content":"For you desire no sacrifice, or else I would give it to you; *","preface":16},{"line_type":"congregation","content":"but you delight not in burnt-offerings."},{"line_type":"leader","content":"The sacrifice of God is a troubled spirit; *","preface":17},{"line_type":"leader","content":"a broken and contrite heart, O God, you shall not despise."},{"line_type":"congregation","content":"O be favorable and gracious unto Zion; *","preface":18},{"line_type":"congregation","content":"may you build up the walls of Jerusalem."},{"line_type":"leader","content":"Then you shall be pleased with the sacrifice of righteousness, with the burnt-offerings and oblations; *","preface":19},{"line_type":"leader","content":"then shall they offer young bullocks upon your altar."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"First Reading","lines":[{"line_type":"heading","content":"The First Lesson"},{"line_type":"subheading","content":"Isaiah 32"},{"line_type":"reader","content":"A reading from the Prophet Isaiah, beginning with the thirty-second chapter, the first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='firstreading_31baaa81-e03f-5a7a-b7d0-efff20b0ba09'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<div class=\"poetry top-1\"><p class=\"line\"><span class=\"chapter-2\"><span class=\"text Isa-32-1\" id=\"en-AKJV-18261\"><span class=\"chapternum\">32\u00a0</span>Behold, a king shall reign in righteousness,</span></span><br/><span class=\"text Isa-32-1\">and princes shall rule in judgment.</span><br/><span class=\"text Isa-32-2\" id=\"en-AKJV-18262\"><sup class=\"versenum\">2\u00a0</sup>And a man shall be as an hiding place from the wind,</span><br/><span class=\"text Isa-32-2\">and a covert from the tempest;</span><br/><span class=\"text Isa-32-2\">as rivers of water in a dry place,</span><br/><span class=\"text Isa-32-2\">as the shadow of a great rock in a weary land.</span><br/><span class=\"text Isa-32-3\" id=\"en-AKJV-18263\"><sup class=\"versenum\">3\u00a0</sup>And the eyes of them that see shall not be dim,</span><br/><span class=\"text Isa-32-3\">and the ears of them that hear shall hearken.</span><br/><span class=\"text Isa-32-4\" id=\"en-AKJV-18264\"><sup class=\"versenum\">4\u00a0</sup>The heart also of the rash shall understand knowledge,</span><br/><span class=\"text Isa-32-4\">and the tongue of the stammerers shall be ready to speak plainly.</span><br/><span class=\"text Isa-32-5\" id=\"en-AKJV-18265\"><sup class=\"versenum\">5\u00a0</sup>The vile person shall be no more called liberal,</span><br/><span class=\"text Isa-32-5\">nor the churl said to be bountiful.</span><br/><span class=\"text Isa-32-6\" id=\"en-AKJV-18266\"><sup class=\"versenum\">6\u00a0</sup>For the vile person will speak villany,</span><br/><span class=\"text Isa-32-6\">and his heart will work iniquity,</span><br/><span class=\"text Isa-32-6\">to practise hypocrisy, and to utter error against the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span>,</span><br/><span class=\"text Isa-32-6\">to make empty the soul of the hungry,</span><br/><span class=\"text Isa-32-6\">and he will cause the drink of the thirsty to fail.</span><br/><span class=\"text Isa-32-7\" id=\"en-AKJV-18267\"><sup class=\"versenum\">7\u00a0</sup>The instruments also of the churl are evil:</span><br/><span class=\"text Isa-32-7\">he deviseth wicked devices to destroy the poor with lying words,</span><br/><span class=\"text Isa-32-7\">even when the needy speaketh right.</span><br/><span class=\"text Isa-32-8\" id=\"en-AKJV-18268\"><sup class=\"versenum\">8\u00a0</sup>But the liberal deviseth liberal things;</span><br/><span class=\"text Isa-32-8\">and by liberal things shall he stand.</span></p><span data-line-id='firstreading_ca6158fa-e7dc-5d73-a361-c4a034dd50d9'></span></div> <div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-32-9\" id=\"en-AKJV-18269\"><sup class=\"versenum\">9\u00a0</sup>Rise up, ye women that are at ease;</span><br/><span class=\"text Isa-32-9\">hear my voice, ye careless daughters;</span><br/><span class=\"text Isa-32-9\">give ear unto my speech.</span><br/><span class=\"text Isa-32-10\" id=\"en-AKJV-18270\"><sup class=\"versenum\">10\u00a0</sup>Many days and years shall ye be troubled, ye careless women:</span><br/><span class=\"text Isa-32-10\">for the vintage shall fail, the gathering shall not come.</span><br/><span class=\"text Isa-32-11\" id=\"en-AKJV-18271\"><sup class=\"versenum\">11\u00a0</sup>Tremble, ye women that are at ease;</span><br/><span class=\"text Isa-32-11\">be troubled, ye careless ones:</span><br/><span class=\"text Isa-32-11\">strip you, and make you bare,</span><br/><span class=\"text Isa-32-11\">and gird sackcloth upon your loins.</span><br/><span class=\"text Isa-32-12\" id=\"en-AKJV-18272\"><sup class=\"versenum\">12\u00a0</sup>They shall lament for the teats,</span><br/><span class=\"text Isa-32-12\">for the pleasant fields, for the fruitful vine.</span><br/><span class=\"text Isa-32-13\" id=\"en-AKJV-18273\"><sup class=\"versenum\">13\u00a0</sup>Upon the land of my people shall come up thorns and briers;</span><br/><span class=\"text Isa-32-13\">yea, upon all the houses of joy in the joyous city:</span><br/><span class=\"text Isa-32-14\" id=\"en-AKJV-18274\"><sup class=\"versenum\">14\u00a0</sup>because the palaces shall be forsaken;</span><br/><span class=\"text Isa-32-14\">the multitude of the city shall be left;</span><br/><span class=\"text Isa-32-14\">the forts and towers shall be for dens for ever,</span><br/><span class=\"text Isa-32-14\">a joy of wild asses, a pasture of flocks;</span><br/><span class=\"text Isa-32-15\" id=\"en-AKJV-18275\"><sup class=\"versenum\">15\u00a0</sup>until the spirit be poured upon us from on high,</span><br/><span class=\"text Isa-32-15\">and the wilderness be a fruitful field,</span><br/><span class=\"text Isa-32-15\">and the fruitful field be counted for a forest.</span><br/><span class=\"text Isa-32-16\" id=\"en-AKJV-18276\"><sup class=\"versenum\">16\u00a0</sup>Then judgment shall dwell in the wilderness,</span><br/><span class=\"text Isa-32-16\">and righteousness remain in the fruitful field.</span><br/><span class=\"text Isa-32-17\" id=\"en-AKJV-18277\"><sup class=\"versenum\">17\u00a0</sup>And the work of righteousness shall be peace;</span><br/><span class=\"text Isa-32-17\">and the effect of righteousness quietness and assurance for ever.</span><br/><span class=\"text Isa-32-18\" id=\"en-AKJV-18278\"><sup class=\"versenum\">18\u00a0</sup>And my people shall dwell in a peaceable habitation,</span><br/><span class=\"text Isa-32-18\">and in sure dwellings, and in quiet resting places;</span><br/><span class=\"text Isa-32-19\" id=\"en-AKJV-18279\"><sup class=\"versenum\">19\u00a0</sup>when it shall hail, coming down on the forest;</span><br/><span class=\"text Isa-32-19\">and the city shall be low in a low place.</span><br/><span class=\"text Isa-32-20\" id=\"en-AKJV-18280\"><sup class=\"versenum\">20\u00a0</sup>Blessed are ye that sow beside all waters,</span><br/><span class=\"text Isa-32-20\">that send forth thither the feet of the ox and the ass.</span></p></div> </div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"First Canticle","lines":[{"line_type":"heading","content":"MAGNIFICAT"},{"line_type":"subheading","content":"The Song of Mary"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"My soul magnifies the Lord, *"},{"line_type":"congregation","content":"and my spirit rejoices in God my Savior;"},{"line_type":"congregation","content":"For he has regarded *"},{"line_type":"congregation","content":"the lowliness of his handmaiden."},{"line_type":"congregation","content":"For behold, from now on, *"},{"line_type":"congregation","content":"all generations will call me blessed;"},{"line_type":"congregation","content":"For he that is mighty has magnified me, *"},{"line_type":"congregation","content":"and holy is his Name."},{"line_type":"congregation","content":"And his mercy is on those who fear him, *"},{"line_type":"congregation","content":"throughout all generations."},{"line_type":"congregation","content":"He has shown the strength of his arm; *"},{"line_type":"congregation","content":"he has scattered the proud in the imagination of their hearts."},{"line_type":"congregation","content":"He has brought down the mighty from their thrones, *"},{"line_type":"congregation","content":"and has exalted the humble and meek."},{"line_type":"congregation","content":"He has filled the hungry with good things, *"},{"line_type":"congregation","content":"and the rich he has sent empty away."},{"line_type":"congregation","content":"He, remembering his mercy, has helped his servant Israel, *"},{"line_type":"congregation","content":"as he promised to our fathers, Abraham and his seed for ever."},{"line_type":"citation","content":"LUKE 1:46-55"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Second Reading","lines":[{"line_type":"heading","content":"The Second Lesson"},{"line_type":"subheading","content":"Luke 4:1-30"},{"line_type":"reader","content":"A reading from the Gospel of our Lord Jesus Christ according to St. Luke, beginning with the fourth chapter, the first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='secondreading_390dd9f8-01fd-550f-b40e-22a6b594b8e9'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<p class=\"top-1 chapter-1\"><span class=\"text Luke-4-1\" id=\"en-AKJV-25065\"><span class=\"chapternum\">4\u00a0</span>And Jesus being full of the Holy Ghost returned from Jordan, and was led by the Spirit into the wilderness, </span> <span class=\"text Luke-4-2\" id=\"en-AKJV-25066\"><sup class=\"versenum\">2\u00a0</sup>being forty days tempted of the devil. And in those days he did eat nothing: and when they were ended, he afterward hungered. </span> <span class=\"text Luke-4-3\" id=\"en-AKJV-25067\"><sup class=\"versenum\">3\u00a0</sup>And the devil said unto him, If thou be the Son of God, command this stone that it be made bread. </span> <span class=\"text Luke-4-4\" id=\"en-AKJV-25068\"><sup class=\"versenum\">4\u00a0</sup>And Jesus answered him, saying, It is written, That man shall not live by bread alone, but by every word of God.</span></p><span data-line-id='secondreading_24c57cb8-0296-5cfa-93ad-bb6bff3622b5'></span> <p><span class=\"text Luke-4-5\" id=\"en-AKJV-25069\"><sup class=\"versenum\">5\u00a0</sup>And the devil, taking him up into an high mountain, shewed unto him all the kingdoms of the world in a moment of time. </span> <span class=\"text Luke-4-6\" id=\"en-AKJV-25070\"><sup class=\"versenum\">6\u00a0</sup>And the devil said unto him, All this power will I give thee, and the glory of them: for that is delivered unto me; and to whomsoever I will I give it. </span> <span class=\"text Luke-4-7\" id=\"en-AKJV-25071\"><sup class=\"versenum\">7\u00a0</sup>If thou therefore wilt worship me, all shall be thine. </span> <span class=\"text Luke-4-8\" id=\"en-AKJV-25072\"><sup class=\"versenum\">8\u00a0</sup>And Jesus answered and said unto him, Get thee behind me, Satan: for it is written, Thou shalt worship the Lord thy God, and him only shalt thou serve.</span></p><span data-line-id='secondreading_98961287-336e-5f0f-ab40-be7ccd97632b'></span> <p><span class=\"text Luke-4-9\" id=\"en-AKJV-25073\"><sup class=\"versenum\">9\u00a0</sup>And he brought him to Jerusalem, and set him on a pinnacle of the temple, and said unto him, If thou be the Son of God, cast thyself down from hence: </span> <span class=\"text Luke-4-10\" id=\"en-AKJV-25074\"><sup class=\"versenum\">10\u00a0</sup>for it is written, He shall give his angels charge over thee, to keep thee: </span> <span class=\"text Luke-4-11\" id=\"en-AKJV-25075\"><sup class=\"versenum\">11\u00a0</sup>and in their hands they shall bear thee up, lest at any time thou dash thy foot against a stone. </span> <span class=\"text Luke-4-12\" id=\"en-AKJV-25076\"><sup class=\"versenum\">12\u00a0</sup>And Jesus answering said unto him, It is said, Thou shalt not tempt the Lord thy God. </span> <span class=\"text Luke-4-13\" id=\"en-AKJV-25077\"><sup class=\"versenum\">13\u00a0</sup>And when the devil had ended all the temptation, he departed from him for a season.</span></p><span data-line-id='secondreading_47280fe8-e049-5e4a-b3c1-283bad06ca63'></span> <p><span class=\"text Luke-4-14\" id=\"en-AKJV-25078\"><sup class=\"versenum\">14\u00a0</sup>And Jesus returned in the power of the Spirit into Galilee: and there went out a fame of him through all the region round about. </span> <span class=\"text Luke-4-15\" id=\"en-AKJV-25079\"><sup class=\"versenum\">15\u00a0</sup>And he taught in their synagogues, being glorified of all.</span></p><span data-line-id='secondreading_90680abe-7823-5ca1-8bd4-f4a147233391'></span> <p><span class=\"text Luke-4-16\" id=\"en-AKJV-25080\"><sup class=\"versenum\">16\u00a0</sup>And he came to Nazareth, where he had been brought up: and, as his custom was, he went into the synagogue on the sabbath day, and stood up for to read. </span> <span class=\"text Luke-4-17\" id=\"en-AKJV-25081\"><sup class=\"versenum\">17\u00a0</sup>And there was delivered unto him the book of the prophet Esaias. And when he had opened the book, he found the place where it was written, </span> <span class=\"text Luke-4-18\" id=\"en-AKJV-25082\"><sup class=\"versenum\">18\u00a0</sup>The Spirit of the Lord is upon me, because he hath anointed me to preach the gospel to the poor; he hath sent me to heal the brokenhearted, to preach deliverance to the captives, and recovering of sight to the blind, to set at liberty them that are bruised, </span> <span class=\"text Luke-4-19\" id=\"en-AKJV-25083\"><sup class=\"versenum\">19\u00a0</sup>to preach the acceptable year of the Lord. </span> <span class=\"text Luke-4-20\" id=\"en-AKJV-25084\"><sup class=\"versenum\">20\u00a0</sup>And he closed the book, and he gave it again to the minister, and sat down. And the eyes of all them that were in the synagogue were fastened on him.</span></p><span data-line-id='secondreading_ba536438-3cee-5b8c-a099-ea89006bb7d3'></span> <p><span class=\"text Luke-4-21\" id=\"en-AKJV-25085\"><sup class=\"versenum\">21\u00a0</sup>And he began to say unto them, This day is this scripture fulfilled in your ears. </span> <span class=\"text Luke-4-22\" id=\"en-AKJV-25086\"><sup class=\"versenum\">22\u00a0</sup>And all bare him witness, and wondered at the gracious words which proceeded out of his mouth. And they said, Is not this Joseph\u2019s son? </span> <span class=\"text Luke-4-23\" id=\"en-AKJV-25087\"><sup class=\"versenum\">23\u00a0</sup>And he said unto them, Ye will surely say unto me this proverb, Physician, heal thyself: whatsoever we have heard done in Capernaum, do also here in thy country. </span> <span class=\"text Luke-4-24\" id=\"en-AKJV-25088\"><sup class=\"versenum\">24\u00a0</sup>And he said, Verily I say unto you, No prophet is accepted in his own country. </span> <span class=\"text Luke-4-25\" id=\"en-AKJV-25089\"><sup class=\"versenum\">25\u00a0</sup>But I tell you of a truth, many widows were in Israel in the days of Elias, when the heaven was shut up three years and six months, when great famine was throughout all the land; </span> <span class=\"text Luke-4-26\" id=\"en-AKJV-25090\"><sup class=\"versenum\">26\u00a0</sup>but unto none of them was Elias sent, save unto Sarepta, a city of Sidon, unto a woman that was a widow. </span> <span class=\"text Luke-4-27\" id=\"en-AKJV-25091\"><sup class=\"versenum\">27\u00a0</sup>And many lepers were in Israel in the time of Eliseus the prophet; and none of them was cleansed, saving Naaman the Syrian.</span></p><span data-line-id='secondreading_28e40a48-7b70-5459-addd-fcad644816a7'></span> <p><span class=\"text Luke-4-28\" id=\"en-AKJV-25092\"><sup class=\"versenum\">28\u00a0</sup>And all they in the synagogue, when they heard these things, were filled with wrath, </span> <span class=\"text Luke-4-29\" id=\"en-AKJV-25093\"><sup class=\"versenum\">29\u00a0</sup>and rose up, and thrust him out of the city, and led him unto the brow of the hill whereon their city was built, that they might cast him down headlong. </span> <span class=\"text Luke-4-30\" id=\"en-AKJV-25094\"><sup class=\"versenum\">30\u00a0</sup>But he passing through the midst of them went his way, </span> </p>\n</div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"Second Canticle","lines":[{"line_type":"heading","content":"NUNC DIMITTIS"},{"line_type":"subheading","content":"The Song of Simeon"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"Lord, now let your servant depart in peace, *"},{"line_type":"congregation","content":"according to your word."},{"line_type":"congregation","content":"For my eyes have seen your salvation, *"},{"line_type":"congregation","content":"which you have prepared before the face of all people;"},{"line_type":"congregation","content":"To be a light to lighten the Gentiles, *"},{"line_type":"congregation","content":"and to be the glory of your people Israel."},{"line_type":"citation","content":"LUKE 2:29-32"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"The Apostle's Creed","lines":[{"line_type":"heading","content":"The Apostles' Creed"},{"line_type":"rubric","content":"Officiant and People together, all standing"},{"line_type":"congregation","content":"I believe in God, the Father almighty,"},{"line_type":"congregation","content":"creator of heaven and earth."},{"line_type":"congregation","content":"I believe in Jesus Christ, his only Son, our Lord."},{"line_type":"congregation","content":"He was conceived by the Holy Spirit"},{"line_type":"congregation","content":"and born of the Virgin Mary."},{"line_type":"congregation","content":"He suffered under Pontius Pilate,"},{"line_type":"congregation","content":"was crucified, died, and was buried."},{"line_type":"congregation","content":"He descended to the dead."},{"line_type":"congregation","content":"On the third day he rose again."},{"line_type":"congregation","content":"He ascended into heaven,"},{"line_type":"congregation","content":"and is seated at the right hand of the Father."},{"line_type":"congregation","content":"He will come again to judge the living and the dead."},{"line_type":"congregation","content":"I believe in the Holy Spirit,"},{"line_type":"congregation","content":"the holy catholic Church,"},{"line_type":"congregation","content":"the communion of saints,"},{"line_type":"congregation","content":"the forgiveness of sins,"},{"line_type":"congregation","content":"the resurrection of the body,"},{"line_type":"congregation","content":"and the life everlasting. Amen."}]},{"name":"The Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"The Lord be with you.","preface":"Officiant"},{"line_type":"congregation_dialogue","content":"And with your spirit.","preface":"People"},{"line_type":"leader_dialogue","content":"Let us pray.","preface":"Officiant"},{"line_type":"rubric","content":"The People kneel or stand."},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"heading","content":"The Suffrages"},{"line_type":"leader_dialogue","content":"That this evening may be holy, good, and peaceful,"},{"line_type":"congregation_dialogue","content":"We entreat you, O Lord."},{"line_type":"leader_dialogue","content":"That your holy angels may lead us in paths of peace and goodwill,"},{"line_type":"congregation_dialogue","content":"We entreat you, O Lord."},{"line_type":"leader_dialogue","content":"That we may be pardoned and forgiven for our sins and offenses,"},{"line_type":"congregation_dialogue","content":"We entreat you, O Lord."},{"line_type":"leader_dialogue","content":"That there may be peace in your Church and in the whole world,"},{"line_type":"congregation_dialogue","content":"We entreat you, O Lord."},{"line_type":"leader_dialogue","content":"That we may depart this life in your faith and fear, and not be condemned before the great judgment seat of Christ,"},{"line_type":"congregation_dialogue","content":"We entreat you, O Lord."},{"line_type":"leader_dialogue","content":"That we may be bound together by your Holy Spirit in the communion of the Blessed Virgin Mary, Hilda, and all your saints, entrusting one another and all our life to Christ,"},{"line_type":"congregation_dialogue","content":"We entreat you, O Lord."}]},{"name":"Collect(s) of the Day","lines":[{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Thursday after the Twenty-fifth Sunday after Pentecost, or the Twenty-fourth Sunday after Trinity (Proper 28)"},{"line_type":"leader","content":"Stir up, O Lord, the wills of your faithful people, that bringing forth in abundance the fruit of good works, they may be abundantly rewarded when our Savior Jesus Christ comes to restore all things; who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Hilda, Abbess of Whitby, 680"},{"line_type":"leader","content":"O God, your blessed Son became poor for our sake, and chose the Cross over the kingdoms of this world: Deliver us from an inordinate love of worldly things, that we, inspired by the devotion of your servant Hilda, may seek you with singleness of heart, behold your glory by faith, and attain to the riches of your everlasting kingdom, where we shall be united with our Savior Jesus Christ; who lives and reigns with you and the Holy Spirit, one God, now and for ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Additional Collects","lines":[{"line_type":"heading","content":"A Collect for the Presence of Christ"},{"line_type":"subheading","content":"Thursday"},{"line_type":"leader","content":"Lord Jesus, stay with us, for evening is at hand and the day is past; be our companion in the way, kindle our hearts, and awaken hope, that we may know you as you are revealed in Scripture and the breaking of bread. Grant this for the sake of your love."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"A Prayer for Mission"},{"line_type":"leader","content":"O God, you manifest in your servants the signs of your presence: Send forth upon us the Spirit of love, that in companionship with one another your abounding grace may increase among us; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Intercessions, Thanksgivings, and Praise","lines":[{"line_type":"heading","content":"Intercessions, Thanksgivings, and Praise"},{"line_type":"rubric","content":"The Officiant may invite the People to offer intercessions and thanksgivings."},{"line_type":"rubric","content":"A hymn or anthem may be sung."},{"line_type":"speaker","content":"Let us pause to offer our own intercessions and thanksgivings."}]},{"name":"Final Prayers","lines":[{"line_type":"heading","content":"The General Thanksgiving"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Almighty God, Father of all mercies,"},{"line_type":"congregation","content":"we your unworthy servants give you humble thanks"},{"line_type":"congregation","content":"for all your goodness and loving-kindness"},{"line_type":"congregation","content":"to us and to all whom you have made."},{"line_type":"congregation","content":"We bless you for our creation, preservation,"},{"line_type":"congregation","content":"and all the blessings of this life;"},{"line_type":"congregation","content":"but above all for your immeasurable love"},{"line_type":"congregation","content":"in the redemption of the world by our Lord Jesus Christ;"},{"line_type":"congregation","content":"for the means of grace, and for the hope of glory."},{"line_type":"congregation","content":"And, we pray, give us such an awareness of your mercies,"},{"line_type":"congregation","content":"that with truly thankful hearts we may show forth your praise,"},{"line_type":"congregation","content":"not only with our lips, but in our lives,"},{"line_type":"congregation","content":"by giving up our selves to your service,"},{"line_type":"congregation","content":"and by walking before you"},{"line_type":"congregation","content":"in holiness and righteousness all our days;"},{"line_type":"congregation","content":"Through Jesus Christ our Lord,"},{"line_type":"congregation","content":"to whom, with you and the Holy Spirit,"},{"line_type":"congregation","content":"be honor and glory throughout all ages. Amen."},{"line_type":"heading","content":"A Prayer of St. John Chrysostom"},{"line_type":"leader","content":"Almighty God, you have given us grace at this time, with one accord to make our common supplications to you; and you have promised through your well-beloved Son that when two or three are gathered together in his Name you will grant their requests: Fulfill now, O Lord, our desires and petitions as may be best for us; granting us in this world knowledge of your truth, and in the age to come life everlasting."},{"line_type":"congregation","content":"Amen."}]},{"name":"Dismissal","lines":[{"line_type":"heading","content":"Dismissal and Grace"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"May the God of hope fill us with all joy and peace in believing through the power of the Holy Spirit."},{"line_type":"congregation","content":"Amen."},{"line_type":"citation","content":"ROMANS 15:13"}]}],"compline":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"rubric","content":"The Officiant begins:"},{"line_type":"leader_dialogue","content":"The Lord Almighty grant us a peaceful night and a perfect end."},{"line_type":"congregation_dialogue","content":"Amen."},{"line_type":"leader_dialogue","content":"Our help is in the Name of the Lord;"},{"line_type":"congregation_dialogue","content":"The maker of heaven and earth."}]},{"name":"Confession","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant continues"},{"line_type":"leader_dialogue","content":"Let us humbly confess our sins unto Almighty God."},{"line_type":"rubric","content":"Silence may be kept. The Officiant and People then say"},{"line_type":"congregation","content":"Almighty God and Father, we confess to you,"},{"line_type":"congregation","content":"to one another, and to the whole company of heaven,"},{"line_type":"congregation","content":"that we have sinned, through our own fault,"},{"line_type":"congregation","content":"in thought, and word, and deed, and in what we have left undone."},{"line_type":"congregation","content":"For the sake of your Son our Lord Jesus Christ,"},{"line_type":"congregation","content":"have mercy upon us, forgive us our sins,"},{"line_type":"congregation","content":"and by the power of your Holy Spirit,"},{"line_type":"congregation","content":"raise us up to serve you in newness of life,"},{"line_type":"congregation","content":"to the glory of your Name. Amen."},{"line_type":"rubric","content":"The Officiant alone says"},{"line_type":"leader","content":"May almighty God grant us forgiveness of all our sins, and the grace and comfort of the Holy Spirit."},{"line_type":"congregation","content":"Amen."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"Invitatory"},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen. Alleluia."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalms"},{"line_type":"heading","content":"Psalm 4"},{"line_type":"subheading","content":"Cum invocarem"},{"line_type":"leader","content":"Hear me when I call, O God of my righteousness; *","preface":1},{"line_type":"leader","content":"you set me free when I was in trouble; have mercy upon me, and hear my prayer."},{"line_type":"congregation","content":"O you children of men, how long will you blaspheme my honor, *","preface":2},{"line_type":"congregation","content":"and have such pleasure in vanity, and seek after falsehood?"},{"line_type":"leader","content":"Know this also, that the L\u1d0f\u0280\u1d05 has chosen for himself the one that is godly; *","preface":3},{"line_type":"leader","content":"when I call upon the L\u1d0f\u0280\u1d05, he will hear me."},{"line_type":"congregation","content":"Stand in awe, and sin not; *","preface":4},{"line_type":"congregation","content":"commune with your own heart upon your bed, and be still."},{"line_type":"leader","content":"Offer the sacrifice of righteousness *","preface":5},{"line_type":"leader","content":"and put your trust in the L\u1d0f\u0280\u1d05."},{"line_type":"congregation","content":"There are many that say, \u201cWho will show us any good?\u201d *","preface":6},{"line_type":"congregation","content":"L\u1d0f\u0280\u1d05, lift up the light of your countenance upon us."},{"line_type":"leader","content":"You have put gladness in my heart, *","preface":7},{"line_type":"leader","content":"more than when others\u2019 grain and wine and oil increased."},{"line_type":"congregation","content":"I will lay me down in peace, and take my rest; *","preface":8},{"line_type":"congregation","content":"for you, L\u1d0f\u0280\u1d05, only, make me dwell in safety."},{"line_type":"heading","content":"Psalm 31:1-6"},{"line_type":"subheading","content":"In te, Domine, speravi"},{"line_type":"leader","content":"In you, O L\u1d0f\u0280\u1d05, have I put my trust; *","preface":1},{"line_type":"leader","content":"let me never be put to confusion; deliver me in your righteousness."},{"line_type":"congregation","content":"Bow down your ear to me, *","preface":2},{"line_type":"congregation","content":"make haste to deliver me,"},{"line_type":"leader","content":"And be my strong rock and house of defense, *","preface":3},{"line_type":"leader","content":"that you may save me."},{"line_type":"congregation","content":"For you are my strong rock and my castle; *","preface":4},{"line_type":"congregation","content":"be also my guide, and lead me for your Name\u2019s sake."},{"line_type":"leader","content":"Draw me out of the net that they have laid secretly for me, *","preface":5},{"line_type":"leader","content":"for you are my strength."},{"line_type":"congregation","content":"Into your hands I commend my spirit, *","preface":6},{"line_type":"congregation","content":"for you have redeemed me, O L\u1d0f\u0280\u1d05, O God of truth."},{"line_type":"heading","content":"Psalm 91"},{"line_type":"subheading","content":"Qui habitat"},{"line_type":"leader","content":"Whoever dwells under the defense of the Most High *","preface":1},{"line_type":"leader","content":"shall abide under the shadow of the Almighty."},{"line_type":"congregation","content":"I will say unto the L\u1d0f\u0280\u1d05, \u201cYou are my refuge and my stronghold, *","preface":2},{"line_type":"congregation","content":"my God in whom I will trust.\u201d"},{"line_type":"leader","content":"For he shall deliver you from the snare of the hunter *","preface":3},{"line_type":"leader","content":"and from the deadly pestilence."},{"line_type":"congregation","content":"He shall defend you under his wings, and you shall be safe under his feathers; *","preface":4},{"line_type":"congregation","content":"his faithfulness and truth shall be your shield and buckler."},{"line_type":"leader","content":"You shall not be afraid of any terror by night, *","preface":5},{"line_type":"leader","content":"nor of the arrow that flies by day,"},{"line_type":"congregation","content":"Of the pestilence that walks in darkness, *","preface":6},{"line_type":"congregation","content":"nor of the sickness that destroys at noonday."},{"line_type":"leader","content":"A thousand shall fall beside you, and ten thousand at your right hand, *","preface":7},{"line_type":"leader","content":"but it shall not come near you."},{"line_type":"congregation","content":"Indeed, with your eyes you shall behold *","preface":8},{"line_type":"congregation","content":"and see the reward of the ungodly."},{"line_type":"leader","content":"Because you have said, \u201cThe L\u1d0f\u0280\u1d05 is my refuge,\u201d *","preface":9},{"line_type":"leader","content":"and have made the Most High your stronghold,"},{"line_type":"congregation","content":"There shall no evil happen to you, *","preface":10},{"line_type":"congregation","content":"neither shall any plague come near your dwelling."},{"line_type":"leader","content":"For he shall give his angels charge over you, *","preface":11},{"line_type":"leader","content":"to keep you in all your ways."},{"line_type":"congregation","content":"They shall bear you in their hands, *","preface":12},{"line_type":"congregation","content":"that you hurt not your foot against a stone."},{"line_type":"leader","content":"You shall tread upon the lion and adder; *","preface":13},{"line_type":"leader","content":"the young lion and the serpent you shall trample under your feet."},{"line_type":"congregation","content":"\u201cBecause he has set his love upon me, therefore I will deliver him; *","preface":14},{"line_type":"congregation","content":"I will lift him up, because he has known my Name."},{"line_type":"leader","content":"He shall call upon me, and I will hear him; *","preface":15},{"line_type":"leader","content":"indeed, I am with him in trouble; I will deliver him and bring him honor."},{"line_type":"congregation","content":"With long life I will satisfy him, *","preface":16},{"line_type":"congregation","content":"and show him my salvation.\u201d"},{"line_type":"heading","content":"Psalm 134"},{"line_type":"subheading","content":"Ecce nunc"},{"line_type":"leader","content":"Behold now, praise the L\u1d0f\u0280\u1d05, *","preface":1},{"line_type":"leader","content":"all you servants of the L\u1d0f\u0280\u1d05,"},{"line_type":"congregation","content":"You that stand by night in the house of the L\u1d0f\u0280\u1d05, *","preface":2},{"line_type":"congregation","content":"even in the courts of the house of our God."},{"line_type":"leader","content":"Lift up your hands in the sanctuary *","preface":3},{"line_type":"leader","content":"and sing praises unto the L\u1d0f\u0280\u1d05."},{"line_type":"congregation","content":"The L\u1d0f\u0280\u1d05 who made heaven and earth *","preface":4},{"line_type":"congregation","content":"give you blessing out of Zion."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Scripture","lines":[{"line_type":"heading","content":"The Reading"},{"line_type":"leader","content":"Be sober-minded; be watchful. Your adversary the devil prowls around like a roaring lion, seeking someone to devour. Resist him, firm in your faith."},{"line_type":"citation","content":"1 PETER 5:8-9"},{"line_type":"leader_dialogue","content":"The Word of the Lord"},{"line_type":"congregation_dialogue","content":"Thanks be to God."}]},{"name":"Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"Into your hands, O Lord, I commend my spirit;"},{"line_type":"congregation_dialogue","content":"For you have redeemed me, O Lord, O God of truth."},{"line_type":"leader_dialogue","content":"Keep me, O Lord, as the apple of your eye;"},{"line_type":"congregation_dialogue","content":"Hide me under the shadow of your wings."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"spacer","content":""},{"line_type":"leader_dialogue","content":"O Lord, hear our prayer"},{"line_type":"congregation_dialogue","content":"And let our cry come to you."},{"line_type":"leader_dialogue","content":"Let us pray."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Evening"},{"line_type":"leader","content":"Visit this place, O Lord, and drive far from it all snares of the enemy; let your holy angels dwell with us to preserve us in peace; and let your blessing be upon us always; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Evening"},{"line_type":"leader","content":"Look down, O Lord, from your heavenly throne, illumine this night with your celestial brightness, and from the children of light banish the deeds of darkness; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Mission"},{"line_type":"leader","content":"Keep watch, dear Lord, with those who work, or watch, or weep this night, and give your angels charge over those who sleep. Tend the sick, Lord Christ; give rest to the weary, bless the dying, soothe the suffering, pity the afflicted, shield the joyous; and all for your love\u2019s sake."},{"line_type":"congregation","content":"Amen."}]},{"name":"Nunc Dimittis","lines":[{"line_type":"heading","content":"Nunc Dimittis"},{"line_type":"subheading","content":"The Song of Simeon"},{"line_type":"rubric","content":"The Officiant and People say or sing the Song of Simeon with this Antiphon, all standing"},{"line_type":"congregation","content":"Guide us waking, O Lord, and guard us sleeping; that awake we may watch with Christ, and asleep we may rest in peace."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Lord, now let your servant depart in peace, *"},{"line_type":"congregation","content":"according to your word."},{"line_type":"congregation","content":"For my eyes have seen your salvation, *"},{"line_type":"congregation","content":"which you have prepared before the face of all people;"},{"line_type":"congregation","content":"To be a light to lighten the Gentiles, *"},{"line_type":"congregation","content":"and to be the glory of your people Israel."},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Guide us waking, O Lord, and guard us sleeping; that awake we may watch with Christ, and asleep we may rest in peace."}]},{"name":"Conclusion","lines":[{"line_type":"heading","content":"The Dismissal"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"The Officiant concludes with the following"},{"line_type":"leader_dialogue","content":"The almighty and merciful Lord, Father, Son, and Holy Spirit, bless us and keep us, this night and evermore."},{"line_type":"congregation_dialogue","content":"Amen."}]}]}};
